"""Tableflow: a tiny waitlist and table-turn tracker for small restaurants."""
import time
from dataclasses import dataclass, field

@dataclass
class Party:
    name: str
    size: int
    added: float = field(default_factory=time.time)

class Waitlist:
    def __init__(self):
        self.queue: list[Party] = []
        self.turns: list[float] = []  # minutes each seated party spent

    def add(self, name: str, size: int) -> int:
        self.queue.append(Party(name, size))
        return len(self.queue)

    def remove(self, name: str) -> bool:
        """Drop a party who left or was seated elsewhere (fixes stale entries)."""
        for i, p in enumerate(self.queue):
            if p.name == name:
                self.queue.pop(i)
                return True
        return False

    def record_turn(self, minutes: float) -> None:
        """Log how long a seated party actually stayed; keeps last 20 for quotes."""
        self.turns.append(minutes)
        self.turns = self.turns[-20:]

    def seat_next(self, free_seats: int) -> Party | None:
        for i, p in enumerate(self.queue):
            if p.size <= free_seats:
                return self.queue.pop(i)
        return None

    def quoted_wait(self, position: int) -> float:
        # Use recent actual turn times; average party-ahead turnover is per 2 seats.
        avg = sum(self.turns) / len(self.turns) if self.turns else 45.0
        return round(avg * (position - 1) / 2, 1)

if __name__ == "__main__":
    w = Waitlist()
    w.add("Lee", 2); w.add("Ortiz", 4); w.add("Chen", 2)
    print("Quoted wait for Chen:", w.quoted_wait(3), "min")
